-- Stage 2 of 2: the clean, conformed rows the marts consume.

-- Source systems replay batches, so the same business key can
-- arrive more than once. Keep the most recently ingested version.
with deduplicated as (
    select
        *,
        row_number() over (partition by case_id order by ingested_at desc nulls last) as _row_rank
    from {{ ref('cln_fact_customer_service_cases') }}
    where _dq_is_valid
)

select
    case_id,
    opened_ts,
    date_key,
    customer_id,
    case_type,
    priority,
    resolution_hours,
    resolved_ts,
    is_resolved,
    breached_sla,
    satisfaction_score,
    source_system_code,
    ingested_at,
    _cleansed_at
from deduplicated
where _row_rank = 1
